import { readdirSync, readFileSync } from 'node:fs';
import path from 'node:path';

import tailwindcss from '@tailwindcss/vite';
import type { Plugin } from 'vite';
import { defineConfig } from 'wxt';

import packageJson from './package.json' with { type: 'json' };
import { BYO_VENDORS, OBSERVER_HOSTS, TELEMETRY_HOST } from './src/config';
import { DEV_ENTRYPOINTS, MANIFEST_NAME, MIN_CHROME_MAJOR } from './src/config-manifest';

// Manifest is generated by WXT from this file plus the entrypoints.
// Hard Rule 8: permissions are minimal and justified in Decisions.md.
// Hard Rule 9: CSP is strict; no remote code, no inline scripts, no eval.
// Sprint 2.0: host_permissions is exactly the two observer hosts (Gmail, Google Calendar), read from src/config.ts
// OBSERVER_HOSTS. An agent host (src/config.ts AGENT_HOSTS) enters only with the content script that reads it, and
// only while its reader is on: every agent reader is off under its vendor's terms (AGENT_READERS; Decisions.md
// [3.0], [3.10]). Pinned by tests/unit/manifest-hosts.spec.ts and the built manifest check in
// tests/e2e/built-bundle.spec.ts (Decisions.md [2.0]).
//
// Content scripts (sprint_2 2.7) live in entrypoints/content/<name>.content.ts, the scope the lint fences hold to
// the read-only rules (eslint-rules/fences.js ACT_SCOPES: attest/no-act, no ledger imports). WXT only discovers
// content scripts at the top of entrypoints/, so the hook below adds these, each named by its file. Their `matches`
// come from src/config.ts OBSERVER_HOSTS: no test build and no other host exists (Decisions.md [2.7]); the E2E tests
// serve fixtures at the vendors' own addresses through Playwright routing instead. Since sprint_4 4.5 each is
// registered at runtime (`registration: 'runtime'`), by the service worker while the person keeps that reader on
// (src/background/readers.ts), so the manifest lists none.
const CONTENT_DIR = path.resolve(import.meta.dirname, 'entrypoints/content');
const CONTENT_SCRIPT = /^([a-z][a-z0-9-]*)\.content\.ts$/;

function contentScripts(): { name: string; inputPath: string; type: 'content-script' }[] {
  return readdirSync(CONTENT_DIR).flatMap((file) => {
    const name = CONTENT_SCRIPT.exec(file)?.[1];
    return name === undefined
      ? []
      : [{ name, inputPath: path.join(CONTENT_DIR, file), type: 'content-script' as const }];
  });
}

// Zod's JSON Schema export (TECH-17). zod classic's schema module imports its two JSON Schema modules and names them
// in every schema constructor, so tree-shaking kept about 17 KB of code Attest never calls (`toJSONSchema()`, the
// Standard Schema `jsonSchema` methods) in each content script and in the worker's chunk. This plugin gives that one
// importer stand-ins instead: each processor and each method factory throws if it is ever called, and
// `aggregateChecks`, which the `.minLength`/`.format` getters read, comes from the real module. The names are read
// from zod's own file at build time, so an upgrade that renames them fails the build or the bundle check
// (tests/unit/lint/zod-json-schema.spec.ts, tests/e2e/built-bundle.spec.ts), never silently.
const ZOD_CLASSIC_SCHEMAS = /[\\/]zod[\\/]v4[\\/]classic[\\/]schemas\.js$/;
const ZOD_PROCESSORS = '../core/json-schema-processors.js';
const ZOD_TO_JSON_SCHEMA = '../core/to-json-schema.js';
const ZOD_STAND_IN = '\0attest-zod-json-schema:';
const UNSHIPPED = `() => { throw new Error('zod JSON Schema is not shipped in Attest'); }`;

/** The names zod classic's schema module reads from `processors`, and imports from the to-json-schema module. */
export function zodJsonSchemaNames(classic: string): { processors: string[]; toJsonSchema: string[] } {
  const code = classic.replace(/^import[^;]*;$/gm, '');
  const processors = [
    ...new Set([...code.matchAll(/\bprocessors\.([A-Za-z_$][\w$]*)/g)].map((m) => m[1] ?? '')),
  ];
  const imported = /import\s*\{([^}]*)\}\s*from\s*["']\.\.\/core\/to-json-schema\.js["']/.exec(classic)?.[1];
  const toJsonSchema = (imported ?? '')
    .split(',')
    .map((name) => name.trim())
    .filter(Boolean);
  if (!processors.includes('aggregateChecks') || toJsonSchema.length === 0) {
    throw new Error('zod classic no longer imports its JSON Schema modules as wxt.config.ts expects');
  }
  return { processors: processors.sort(), toJsonSchema: toJsonSchema.sort() };
}

/** The stand-in for `source` (one of the two modules) as imported by zod classic's schema module at `importer`. */
export function zodStandIn(source: string, importer: string): string {
  const names = zodJsonSchemaNames(readFileSync(importer, 'utf8'));
  if (source === ZOD_TO_JSON_SCHEMA) {
    return names.toJsonSchema.map((name) => `export const ${name} = () => ${UNSHIPPED};`).join('\n');
  }
  const real = JSON.stringify(path.resolve(path.dirname(importer), ZOD_PROCESSORS));
  const stubs = names.processors.filter((name) => name !== 'aggregateChecks');
  return [
    `export { aggregateChecks } from ${real};`,
    ...stubs.map((name) => `export const ${name} = ${UNSHIPPED};`),
  ].join('\n');
}

/** The Vite plugin of the comment above. */
export function zodWithoutJsonSchema(): Plugin {
  return {
    name: 'attest:zod-without-json-schema',
    enforce: 'pre',
    resolveId(source, importer) {
      if (importer === undefined || !ZOD_CLASSIC_SCHEMAS.test(importer)) return null;
      if (source !== ZOD_PROCESSORS && source !== ZOD_TO_JSON_SCHEMA) return null;
      return `${ZOD_STAND_IN}${source}|${importer}`;
    },
    load(id) {
      if (!id.startsWith(ZOD_STAND_IN)) return null;
      const [source = '', importer = ''] = id.slice(ZOD_STAND_IN.length).split('|');
      return zodStandIn(source, importer);
    },
  };
}

/**
 * The zip's name: `attest-<version>.zip` for the store build alone, `attest-<version>-dev.zip` for any other, so a
 * development zip is never the file the release step checks and uploads (Sprint 7 close, security review SEC-5).
 */
export function zipTemplate(release: boolean): string {
  return release ? '{{name}}-{{version}}.zip' : '{{name}}-{{version}}-dev.zip';
}

/** `infos` without the development pages when `release` is set: what a release build makes. */
export function releaseEntrypoints<T extends { readonly name: string }>(infos: T[], release: boolean): T[] {
  return release ? infos.filter((info) => !DEV_ENTRYPOINTS.includes(info.name)) : infos;
}

/** What PRIVACY.md holds where the founder has still to write something in before a release (MANUAL.md, Sprint 7). */
export const POLICY_TO_FILL = '[to fill before release';

/**
 * Refuses a release build whose telemetry host is still the `.invalid` stand-in (src/config.ts TELEMETRY_HOST; sprint_5
 * 5.7): a store build must post, when the person opts in, to the API the founder deployed (MANUAL.md, Sprint 5). Also
 * refuses one while `policy`, PRIVACY.md, still holds a blank to fill or does not name that host (Sprint 7 close, tech
 * review TECH-6, privacy review gaps 7 and 8): the policy a store install points to says who runs the server, how to
 * reach them privately, and where the numbers go.
 */
export function assertReleasable(release: boolean, telemetryHost: string, policy: string): void {
  if (!release) return;
  if (telemetryHost.endsWith('.invalid')) {
    throw new Error(
      `pnpm build:release: the telemetry host is still ${telemetryHost}. Set src/config.ts TELEMETRY_HOST to the deployed telemetry API first (MANUAL.md, Sprint 5).`,
    );
  }
  if (policy.includes(POLICY_TO_FILL)) {
    throw new Error(
      `pnpm build:release: PRIVACY.md still holds "${POLICY_TO_FILL}": write in the server's operator and the private contact first (MANUAL.md, Sprint 7).`,
    );
  }
  if (!policy.includes(telemetryHost)) {
    throw new Error(
      `pnpm build:release: PRIVACY.md does not name the telemetry host ${telemetryHost}. Name it where it describes the usage numbers (MANUAL.md, Sprint 7).`,
    );
  }
}

/**
 * Every host an extension page or the service worker may connect to (Sprint 5 close, security review SEC-3; Hard Rule
 * 1): the extension itself, each model vendor's endpoint and the telemetry host. Chrome refuses any other host, a
 * redirect's target among them, whatever a script asks. Which of these is ever called is the person's choice
 * (src/config-network.ts `allowedHosts`): none while every option is off.
 */
export function connectSources(): string[] {
  const vendors = Object.values(BYO_VENDORS).map(({ endpoint }) => new URL(endpoint).origin);
  return ["'self'", ...vendors, `https://${TELEMETRY_HOST}`];
}

/**
 * The content security policy of the extension's pages and service worker (Hard Rule 9; `connectSources`): everything
 * from the extension alone (`default-src`), images also from `blob:` (the share image's preview, made in the page from
 * its own canvas), no plugin, no form sent anywhere, and the hosts `connectSources` names (Sprint 6 close, security
 * review SEC-3: until then images, styles, fonts and frames could come from any host).
 */
export const EXTENSION_PAGES_CSP = [
  "default-src 'self'",
  "script-src 'self'",
  "object-src 'none'",
  "img-src 'self' blob:",
  "form-action 'none'",
  `connect-src ${connectSources().join(' ')}`,
].join('; ');

/**
 * `csp` with WXT's development server (`origin`, `http://localhost:<port>`) also allowed to connect, by http and by
 * WebSocket: `pnpm dev` reloads pages through it. Only the development command calls this.
 */
export function withDevServer(csp: string, origin: string): string {
  return csp.replace('connect-src ', `connect-src ${origin} ${origin.replace(/^http/u, 'ws')} `);
}

export default defineConfig({
  hooks: {
    'build:manifestGenerated': (wxt, manifest) => {
      const csp = manifest.content_security_policy;
      // An MV3 manifest's policy is an object; the string form is MV2's.
      if (wxt.config.command !== 'serve' || wxt.server === undefined || typeof csp !== 'object') return;
      csp.extension_pages = withDevServer(csp.extension_pages ?? '', wxt.server.origin);
    },
    'entrypoints:found': (_wxt, infos) => {
      const release = process.env.ATTEST_RELEASE === '1';
      const policy = release ? readFileSync(path.join(import.meta.dirname, '..', 'PRIVACY.md'), 'utf8') : '';
      assertReleasable(release, TELEMETRY_HOST, policy);
      infos.push(...contentScripts());
      const kept = releaseEntrypoints([...infos], process.env.ATTEST_RELEASE === '1');
      infos.splice(0, infos.length, ...kept);
    },
  },
  // Explicit imports everywhere; no magic globals in reviewed code.
  imports: false,
  manifestVersion: 3,
  manifest: {
    // The store shows the manifest's name as the item's title, and its description as the summary (launch/store-listing.md).
    name: MANIFEST_NAME,
    description: packageJson.description,
    minimum_chrome_version: String(MIN_CHROME_MAJOR),
    // Never in incognito tabs (Decisions [2.close] S3, SEC-9): the ledger is the regular profile's IndexedDB and
    // outlives an incognito session, so an incognito Gmail or Calendar page is never read (Hard Rules 2, 11).
    incognito: 'not_allowed',
    // `scripting` (sprint_4 4.5; Decisions [4.5]): the page readers' content scripts are registered at runtime, so a
    // reader the person turns off is unregistered (src/background/readers.ts). Host access stays the two observer hosts.
    // `notifications` (sprint_4 4.6; Decisions [4.6]): one alert per FINAL NOT_FOUND, UNASKED or OVER_SCOPE receipt.
    permissions: ['storage', 'alarms', 'scripting', 'notifications'],
    // Away detection is opt-in (sprint_3 3.14, Hard Rule 8): the options page asks for it when the person turns it on.
    optional_permissions: ['idle'],
    host_permissions: [...OBSERVER_HOSTS.gmail, ...OBSERVER_HOSTS.gcal],
    content_security_policy: {
      extension_pages: EXTENSION_PAGES_CSP,
    },
    // action.default_title comes from the <title> of entrypoints/popup/index.html: WXT rebuilds
    // manifest.action from the popup entrypoint, so a title set here would be dropped (TECH-14).
  },
  zip: {
    artifactTemplate: zipTemplate(process.env.ATTEST_RELEASE === '1'),
  },
  vite: () => ({
    plugins: [tailwindcss(), zodWithoutJsonSchema()],
    oxc: {
      jsx: { runtime: 'automatic', importSource: 'preact' },
    },
    build: {
      // Readable output for store review (no obfuscation); source maps kept for CI artifacts.
      sourcemap: true,
      // Vite's modulepreload polyfill contains a fetch(); Chrome >= 66 never needs it (we require 120), and the
      // shipped bundle must grep clean for network calls (SECURITY-6, tests/e2e/built-bundle.spec.ts).
      modulePreload: { polyfill: false },
      // ASCII-only output (sprint_2 2.7, Decisions.md [2.7]): Chrome refuses to load an extension whose content
      // script holds a Unicode noncharacter, and the minifier otherwise writes the `\uFDD0` and `\u{1FFFE}` escapes of
      // src/core/unicode-baseline.ts out as raw characters. Every non-ASCII character is written as an escape instead.
      rolldownOptions: {
        output: { minify: { compress: true, mangle: true, codegen: { asciiOnly: true } } },
      },
    },
  }),
});
